// buildDebugGasTable constructs a per-opcode static gas cost table.
// Used by the tracer to report cost in OnOpcode/OnFault hooks.
func buildDebugGasTable(fg ForkGas) [256]uint64 {
	var t [256]uint64
	t[0x01] = spec.GasVerylow             // ADD
	t[0x02] = spec.GasLow                 // MUL
	t[0x03] = spec.GasVerylow             // SUB
	t[0x04] = spec.GasLow                 // DIV
	t[0x05] = spec.GasLow                 // SDIV
	t[0x06] = spec.GasLow                 // MOD
	t[0x07] = spec.GasLow                 // SMOD
	t[0x08] = spec.GasMid                 // ADDMOD
	t[0x09] = spec.GasMid                 // MULMOD
	t[0x0A] = spec.GasHigh                // EXP
	t[0x0B] = spec.GasLow                 // SIGNEXTEND
	t[0x10] = spec.GasVerylow             // LT
	t[0x11] = spec.GasVerylow             // GT
	t[0x12] = spec.GasVerylow             // SLT
	t[0x13] = spec.GasVerylow             // SGT
	t[0x14] = spec.GasVerylow             // EQ
	t[0x15] = spec.GasVerylow             // ISZERO
	t[0x16] = spec.GasVerylow             // AND
	t[0x17] = spec.GasVerylow             // OR
	t[0x18] = spec.GasVerylow             // XOR
	t[0x19] = spec.GasVerylow             // NOT
	t[0x1A] = spec.GasVerylow             // BYTE
	t[0x1B] = spec.GasVerylow             // SHL
	t[0x1C] = spec.GasVerylow             // SHR
	t[0x1D] = spec.GasVerylow             // SAR
	t[0x1E] = spec.GasLow                 // CLZ
	t[0x20] = spec.GasKeccak256           // KECCAK256
	t[0x30] = spec.GasBase                // ADDRESS
	t[0x31] = fg.Balance                  // BALANCE
	t[0x32] = spec.GasBase                // ORIGIN
	t[0x33] = spec.GasBase                // CALLER
	t[0x34] = spec.GasBase                // CALLVALUE
	t[0x35] = spec.GasVerylow             // CALLDATALOAD
	t[0x36] = spec.GasBase                // CALLDATASIZE
	t[0x37] = spec.GasVerylow             // CALLDATACOPY
	t[0x38] = spec.GasBase                // CODESIZE
	t[0x39] = spec.GasVerylow             // CODECOPY
	t[0x3A] = spec.GasBase                // GASPRICE
	t[0x3B] = fg.ExtCodeSize              // EXTCODESIZE
	t[0x3C] = fg.ExtCodeSize              // EXTCODECOPY
	t[0x3D] = spec.GasBase                // RETURNDATASIZE
	t[0x3E] = spec.GasVerylow             // RETURNDATACOPY
	t[0x3F] = fg.ExtCodeHash              // EXTCODEHASH
	t[0x40] = spec.GasBlockhash           // BLOCKHASH
	t[0x41] = spec.GasBase                // COINBASE
	t[0x42] = spec.GasBase                // TIMESTAMP
	t[0x43] = spec.GasBase                // NUMBER
	t[0x44] = spec.GasBase                // DIFFICULTY
	t[0x45] = spec.GasBase                // GASLIMIT
	t[0x46] = spec.GasBase                // CHAINID
	t[0x47] = spec.GasLow                 // SELFBALANCE
	t[0x48] = spec.GasBase                // BASEFEE
	t[0x49] = spec.GasVerylow             // BLOBHASH
	t[0x4A] = spec.GasBase                // BLOBBASEFEE
	t[0x4B] = spec.GasBase                // SLOTNUM
	t[0x50] = spec.GasBase                // POP
	t[0x51] = spec.GasVerylow             // MLOAD
	t[0x52] = spec.GasVerylow             // MSTORE
	t[0x53] = spec.GasVerylow             // MSTORE8
	t[0x54] = fg.Sload                    // SLOAD
	t[0x56] = spec.GasMid                 // JUMP
	t[0x57] = spec.GasHigh                // JUMPI
	t[0x58] = spec.GasBase                // PC
	t[0x59] = spec.GasBase                // MSIZE
	t[0x5A] = spec.GasBase                // GAS
	t[0x5B] = spec.GasJumpdest            // JUMPDEST
	t[0x5C] = spec.GasWarmStorageReadCost // TLOAD
	t[0x5D] = spec.GasWarmStorageReadCost // TSTORE
	t[0x5E] = spec.GasVerylow             // MCOPY
	t[0xE6] = spec.GasVerylow             // DUPN
	t[0xE7] = spec.GasVerylow             // SWAPN
	t[0xE8] = spec.GasVerylow             // EXCHANGE
	t[0xF1] = fg.Call                     // CALL
	t[0xF2] = fg.Call                     // CALLCODE
	t[0xF4] = fg.Call                     // DELEGATECALL
	t[0xFA] = fg.Call                     // STATICCALL
	t[0xFF] = fg.Selfdestruct             // SELFDESTRUCT
	t[0x5F] = spec.GasBase                // PUSH0
	for i := byte(0x60); i <= 0x7F; i++ {
		t[i] = spec.GasVerylow
	} // PUSH1-PUSH32
	for i := byte(0x80); i <= 0x8F; i++ {
		t[i] = spec.GasVerylow
	} // DUP1-DUP16
	for i := byte(0x90); i <= 0x9F; i++ {
		t[i] = spec.GasVerylow
	} // SWAP1-SWAP16
	for i := byte(0xA0); i <= 0xA4; i++ {
		t[i] = spec.GasLog
	} // LOG0-LOG4
	return t
}

// DebugGasTableForFork returns a per-opcode static gas table for the given fork.
// Allocated once per tracing session; cost is negligible.
func DebugGasTableForFork(forkID spec.ForkID) *[256]uint64 {
	t := buildDebugGasTable(NewForkGas(forkID))
	return &t
}
